{
  "name": "@landry_pouth/coding-flow",
  "version": "0.14.0",
  "description": "AI-native engineering workflow that makes Claude Code, OpenCode and Codex reliable on real projects: plan, implement, and verify with executed proof that the tests actually ran and passed — not the agent's word. Optional evidence & audit layer for teams that need governance.",
  "license": "MIT",
  "author": "Landry Pouth",
  "type": "commonjs",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/LandryPouth/coding-flow.git"
  },
  "bugs": {
    "url": "https://github.com/LandryPouth/coding-flow/issues"
  },
  "homepage": "https://github.com/LandryPouth/coding-flow#readme",
  "bin": {
    "coding-flow": "./bin/ai-flow.js",
    "ai-flow": "./bin/ai-flow.js"
  },
  "files": [
    "bin",
    "templates",
    "README.md",
    "CHANGELOG.md",
    "LICENSE"
  ],
  "publishConfig": {
    "access": "public"
  },
  "scripts": {
    "test": "node --require ./scripts/test-env-guard.js --test",
    "check": "node bin/ai-flow.js doctor",
    "pack:dry": "npm pack --dry-run",
    "release": "node scripts/release.mjs",
    "prepublishOnly": "npm test"
  },
  "engines": {
    "node": ">=18"
  },
  "keywords": [
    "ai",
    "agents",
    "claude-code",
    "opencode",
    "codex",
    "workflow",
    "governance",
    "evidence"
  ]
}
